import itertools

def solve():
    n = 13
    # Sum of x = 1, so there are 7 ones and 6 minus ones.
    # Number of ways to choose 7 positions out of 13 is 13C7 = 1716.

    def get_sequences(n):
        # Generate all sequences of length n with sum 1
        # (n+1)/2 ones and (n-1)/2 minus ones
        ones = (n + 1) // 2
        minus_ones = (n - 1) // 2
        seq = [1] * ones + [-1] * minus_ones
        return set(itertools.permutations(seq))

    def get_autocorrelation(seq):
        n = len(seq)
        ac = [0] * n
        for k in range(n):
            s = 0
            for i in range(n):
                s += seq[i] * seq[(i + k) % n]
            ac[k] = s
        return ac

    # This might be too slow if we iterate over all pairs.
    # Let's try to optimize.

    all_seqs = list(get_sequences(n))
    # Precompute autocorrelations
    acs = [get_autocorrelation(s) for s in all_seqs]

    for i in range(len(all_seqs)):
        for j in range(i, len(all_seqs)):
            # Check condition: acs[i][k] + acs[j][k] == -2 for k in 1..6
            match = True
            for k in range(1, 7):
                if acs[i][k] + acs[j][k] != -2:
                    match = False
                    break
            if match:
                return list(all_seqs[i]), list(all_seqs[j])
    return None

