def solve():
    n = 13
    ones = (n + 1) // 2
    minus_ones = (n - 1) // 2
    seq = [1] * ones + [-1] * minus_ones

    # Generate all unique permutations
    all_seqs = list(set(itertools.permutations(seq)))

    # Precompute acs
    # Let's use a list of tuples for faster access
    ac_map = {}
    for s in all_seqs:
        ac = get_autocorrelation(s)
        ac_map[ac] = s

    for ac_i, s_i in ac_map.items():
        target = tuple(-2 - val for val in ac_i)
        if target in ac_map:
            s_j = ac_map[target]
            return list(s_i), list(s_j)
    return None

